private static Map<TypeVariable<?>, Type> buildTypeVariableMap(Class<?> clazz) {
    Map<TypeVariable<?>, Type> map = new java.util.HashMap<>();
    // Walk up the hierarchy
    java.util.Deque<Class<?>> stack = new java.util.ArrayDeque<>();
    stack.push(clazz);
    while (!stack.isEmpty()) {
        Class<?> c = stack.pop();
        Type genericSuper = c.getGenericSuperclass();
        if (genericSuper instanceof ParameterizedType) {
            ParameterizedType pSuper = (ParameterizedType) genericSuper;
            Class<?> raw = (Class<?>) pSuper.getRawType();
            TypeVariable<?>[] vars = raw.getTypeParameters();
            Type[] args = pSuper.getActualTypeArguments();
            for (int j = 0; j < vars.length; j++) {
                if (!map.containsKey(vars[j])) {
                    map.put(vars[j], args[j]);
                }
            }
            stack.push(raw);
        }
        for (Type iface : c.getGenericInterfaces()) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType pIface = (ParameterizedType) iface;
                Class<?> raw = (Class<?>) pIface.getRawType();
                TypeVariable<?>[] vars = raw.getTypeParameters();
                Type[] args = pIface.getActualTypeArguments();
                for (int j = 0; j < vars.length; j++) {
                    if (!map.containsKey(vars[j])) {
                        map.put(vars[j], args[j]);
                    }
                }
                stack.push(raw);
            } else if (iface instanceof Class<?>) {
                stack.push((Class<?>) iface);
            }
        }
    }
    return map;
}

