public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType paramType = (ParameterizedType) genericType;
    Type rawType = paramType.getRawType();
    if (!(rawType instanceof Class<?>)) {
        return null;
    }
    Class<?> rawClass = (Class<?>) rawType;
    // Find the matching type in targetType hierarchy
    Type matched = findMatchingType(targetType, rawClass);
    if (!(matched instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType matchedParam = (ParameterizedType) matched;
    // Build mapping between type variables of rawClass and matchedParam arguments
    TypeVariable<?>[] vars = rawClass.getTypeParameters();
    Type[] matchedArgs = matchedParam.getActualTypeArguments();
    if (vars.length != matchedArgs.length) {
        return null;
    }
    java.util.Map<TypeVariable<?>, Type> typeVarMap = new java.util.HashMap<>();
    for (int i = 0; i < vars.length; i++) {
        typeVarMap.put(vars[i], matchedArgs[i]);
    }
    // Resolve each argument in the original genericType
    Type[] originalArgs = paramType.getActualTypeArguments();
    Class<?>[] res = new Class<?>[originalArgs.length];
    for (int i = 0; i < originalArgs.length; i++) {
        Type resolved = resolveType(originalArgs[i], typeVarMap);
        Class<?> clazz = getClassFromType(resolved);
        if (clazz == null) {
            return null;
        }
        res[i] = clazz;
    }
    return res;
}

