private static Type resolveType(Type t, java.util.Map<TypeVariable<?>, Type> map) {
    if (t instanceof TypeVariable<?>) {
        Type mapped = map.get(t);
        if (mapped == null) {
            return t;
        }
        return resolveType(mapped, map);
    }
    return t;
}

private static Class<?> getClassFromType(Type t) {
    if (t instanceof Class<?>) {
        return (Class<?>) t;
    }
    if (t instanceof ParameterizedType) {
        return getClassFromType(((ParameterizedType) t).getRawType());
    }
    return null;
}

private static Type findMatchingType(Class<?> clazz, Class<?> targetRaw) {
    if (clazz == null) {
        return null;
    }
    if (clazz.equals(targetRaw)) {
        return clazz;
    }
    // check interfaces
    for (Type it : clazz.getGenericInterfaces()) {
        if (it instanceof ParameterizedType) {
            ParameterizedType pit = (ParameterizedType) it;
            if (pit.getRawType() instanceof Class<?> && ((Class<?>) pit.getRawType()).equals(targetRaw)) {
                return pit;
            }
        }
        if (it instanceof Class<?>) {
            Type res = findMatchingType((Class<?>) it, targetRaw);
            if (res != null) return res;
        }
    }
    // check superclass
    Type superT = clazz.getGenericSuperclass();
    if (superT != null) {
        if (superT instanceof ParameterizedType) {
            ParameterizedType pst = (ParameterizedType) superT;
            if (pst.getRawType() instanceof Class<?> && ((Class<?>) pst.getRawType()).equals(targetRaw)) {
                return pst;
            }
        }
        if (superT instanceof Class<?>) {
            return findMatchingType((Class<?>) superT, targetRaw);
        }
    }
    return null;
}

